#include <Arduino.h>
#include <Preferences.h>
Preferences preferences;
void setup() {
    Serial.begin(115200);
    preferences.begin("settings", false);
    preferences.putInt("sample_rate", 10);
    Serial.println(preferences.getInt("sample_rate", 0));
    preferences.end();
}
void loop() { delay(1000); }

